const WEIS12 = ['Kyle Weisbrod, "Tuesday Tips: 12 Scrimmage Modifications to Reinforce Skills" (Ultiworld, 2015)', 'https://ultiworld.com/2015/11/03/tuesday-tips-12-scrimmage-modifications-to-reinforce-skills-presented-by-five-ultimate'];
